# arcgis-stat-card
## Overview
The arcgis-stat-card is a display component that is used to show off a statistic with varying UI customizations. To allow a user to edit the arcgis-stat-card, the arcgis-stat-card should be used with the arcgis-stat-card-editor -- this means that the arcgis-stat-card should be wrapped in an arcgis-hub-metric-card resolver component.

### Usage with arcgis-hub-metric-card
The arcgis-stat-card is often used with the arcgis-hub-metric-card and arcgis-stat-card-editor components. The arcgis-stat-card-editor is used to select what and how to display the arcgis-stat-card -- these values are sent emitted to the consuming UI. The consuming UI must listen for these values and transform them into metric and card configuration objects. These are then passed to the arcgis-hub-metric-card, resolved, and passed to the arcgis-stat-card.

### Utilizing layouts
The stat card has multiple layouts with multiple elements; each layout affects the styling of the card. Because there are so many versions of the stat card's appearance, there is a pattern for adding and modifying layouts within the stat card.

Elements within the stat card that are dependent on the layout selected should have `class={layout}` on the element. This keeps all layout styling changes centralized in the css and does not mix styling with the logic of the stat card's props. 

In the css file, the styling rules for an element that is only used in the more info layout would look something like: 

```css

/* default rules */
div {
  @apply hidden;
}

/* rules for the more info layout */
div.moreInfo {
  @apply block, top-0, left-0, absolute, ...; 
}
```

for a tsx file that looks something like: 

```tsx
<div class={layout}> Shown only in more info. </div>
```

If a layout needs to use an existing element from another layout, do not edit the jsx -- the css file should be edited to add that layout's class. 

### Palette

Developers can interactively explore how theme colors apply to components using the `Theme` storybook addon.

`ArcgisStatCard` wraps `CalciteCard` which determines what theme colors are applied.

#### Color Mappings

ui element / props | calcite theme color
-----------|----------------------|
header / `card-title` | `--calcite-ui-text-1`
`subtitle` | `--calcite-ui-text-2`
main / `value`, `unit` | `calcite-ui-brand` unless overridden with `value-color` prop
`trailing-text` | `--calcite-ui-text-3`

## Examples

### Example of standalone arcgis-stat-card

```html
<arcgis-stat-card
  cardTitle="Title"
  popoverTitle="Title within popover"
  popoverDescription="Description within popover"
  layout="More Info"
  trailingText="trailing text..."
  value="14" />
```

### Example with arcgis-stat-card-editor and arcgis-hub-metric-card
```html
    <div>
      <arcgis-stat-card-editor class="column-6" disabled="true"></arcgis-stat-card-editor>
    </div>
    <div>
      <arcgis-hub-metric-card id="c123" class="column-6"></arcgis-hub-metric-card>
    </div>
    <calcite-button onclick="signIn()">Sign in</calcite-button>
    <calcite-button onclick="signOut()">Sign out</calcite-button>
      <script>
    const values = {
      value: "42",
      units: "%",
      name: "This is the title",
      cardTitle: "This is the title",
      displayType: 'stat-card',
      shareable: true,
      shareableByValue: false,
      // shareableOnHover: true,
      trailingText: "this is the trailing text..."
    };

    const cardEditor = document.querySelector('arcgis-stat-card-editor');
    const card = document.querySelector('arcgis-hub-metric-card');


    cardEditor.values = values;
    cardEditor.themeColors = ['#f40afc', '#fcaf0a', '#0a8cfc', '#fc0a85']


    function updateMetricCardValues(newValues) {
      const cardId = 'c123'; // gotten from project or from card settings from site layout

      // consuming UI must transform values into metric and cardConfig
      const site = { item: { id: 'siteId', title: 'Site title' } };
      const metric = getMetric(newValues, site);
      const cardConfig = getCardConfig(newValues);

      cardConfig.metricId = cardId; // consuming ui will add on if wanted to persist
      metric.id = cardId;
      metric.entityInfo = { name: "My site", type: "site", id: "12345" }

      card.metric = metric;
      card.cardConfig = cardConfig;
    }

    function getMetric(values, site) {
      const { value, itemId, layerId, field, statistic, type, cardTitle, cardId } = values;
      const { id, title } = site.item;
      // create source
      const source = type === 'dynamic'
        ? {
          type: 'service-query',
          serviceUrl: getFeatureServiceUrl(itemId),
          layerId: layerId,
          field: field,
          statistic: statistic,
        }
        : {
          type: 'static-value',
          value: value,
        };

      const entityInfo = {
        id,
        name: title,
        type: 'site',
      };

      const metric = {
        source,
        name: cardTitle,
        entityInfo,
        id: cardId,
      };

      return metric;
    }

    function getCardConfig(values) {
      const { value, itemId, layerId, field, statistic, cardId, ...cardConfig } = values;
      if (!cardConfig.displayType) {
        cardConfig.displayType = 'stat-card';
      }
      if (!cardConfig.metricId) {
        cardConfig.metricId = cardId;
      }
      return cardConfig;
    };

    // TODO:
    function getFeatureServiceUrl(itemId) {
      console.log('item id: ', itemId);
      const tempFakeUrl = 'https://servicesqa.arcgis.com/T5cZDlfUaBpDnk6P/arcgis/rest/services/2019_US_coastline/FeatureServer';
      return tempFakeUrl;
    };

    updateMetricCardValues(values);

    // listen to card editor
    cardEditor.addEventListener('arcgisStatCardEditorChange', evt => {
      console.log(evt.detail);
      if (evt.detail.valid) {
        updateMetricCardValues(evt.detail.values);
      }
    });

    cardEditor.addEventListener('arcgisConfigurationEditorChange', evt => {
      console.log('GOT arcgisConfigurationEditorChange EVENT');
    });

    // auth logic to add context
    function signIn() {
      const evt = new CustomEvent('arcgisAppIdentityStartSignIn')
      document.dispatchEvent(evt);
    }
    function signOut() {
      const evt = new CustomEvent('arcgisAppIdentityStartSignOut')
      document.dispatchEvent(evt);
    }
    document.addEventListener('arcgisAppIdentitySignedIn', (evt) => {
      cardEditor.context = evt.detail;
      card.context = evt.detail;
      showUserInfo(evt.detail.session);
    });
    document.addEventListener('arcgisAppIdentitySignedOut', (evt) => {
      cardEditor.context = evt.detail;
      card.context = evt.detail;
      showUserInfo(evt.detail.session);
    });

  </script>
```

## Status
The component is currently in development with plans to go into production alongside the new arcgis-hub-metric-card. 
Future functionality will include UI enhancements such as displaying charts by selecting a layout.

## Technical

The arcgis-stat-card is a "dumb" component, as it just takes values and renders them. The techincal complexity is within the arcgis-hub-metric-card component and its communication with the arcgis-stat-card-editor component -- refer to those README.mds for a deeper understanding of these components.

For more information, see [Metric Definition and Resolution documentation](https://confluencewikidev.esri.com/display/Hub/Metric+Definition+and+Resolution) and [Stat Card & Editor documentation](https://confluencewikidev.esri.com/pages/viewpage.action?pageId=246416673).

# arcgis-stat-card-editor

## Overview
The arcgis-stat-card-editor is an editor component used by a user to configure the arcgis-stat-card. It is intended to emit values to a listening arcgis-hub-metric-card component, passing it the props it needs to render correctly.

## Examples
```html
<arcgis-stat-card-editor />
...
<arcgis-hub-metric-card />

<script>
  // current set values of configuration editor
  const values = {
    value: "42",
    units: "%",
    name: "This is the title",
    cardTitle: "This is the title",
    displayType: 'stat-card',
    shareable: true,
    shareableByValue: false,
    // shareableOnHover: true,
    trailingText: "this is the trailing text..."
  }

  const cardEditor = document.querySelector('arcgis-stat-card-editor');
  const card = document.querySelector('arcgis-hub-metric-card');

  // updates values in the stat card
  function updateMetricCardValues(newValues) {
    const cardId = 'c123'; // gotten from project or from card settings from site layout

    // consuming UI must transform values into metric and cardConfig
    const site = { item: { id: 'siteId', title: 'Site title' } };
    const metric = getMetric(newValues, site);
    const cardConfig = getCardConfig(newValues);

    cardConfig.metricId = cardId; // od-ui will add on if wanted to persist
    metric.id = cardId;
    metric.entityInfo = { name: "My site", type: "site", id: "12345" }

    card.metric = metric;
    card.cardConfig = cardConfig;
  }

  function getMetric(values, site) {
    const { value, itemId, layerId, field, statistic, type, cardTitle, cardId } = values;
    const { id, title } = site.item;
    // create source
    const source = type === 'dynamic'
      ? {
        type: 'service-query',
        serviceUrl: getFeatureServiceUrl(itemId),
        layerId: layerId,
        field: field,
        statistic: statistic,
      }
      : {
        type: 'static-value',
        value: value,
      };

    const entityInfo = {
      id,
      name: title,
      type: 'site',
    };

    const metric = {
      source,
      name: cardTitle,
      entityInfo,
      id: cardId,
    };

    return metric;
  }

  function getCardConfig(values) {
    const { value, itemId, layerId, field, statistic, cardId, ...cardConfig } = values;
    if (!cardConfig.displayType) {
      cardConfig.displayType = 'stat-card';
    }
    if (!cardConfig.metricId) {
      cardConfig.metricId = cardId;
    }
    return cardConfig;
  };

  function getFeatureServiceUrl(itemId) {
    const tempFakeUrl = 'https://servicesqa.arcgis.com/T5cZDlfUaBpDnk6P/arcgis/rest/services/2019_US_coastline/FeatureServer';
    return tempFakeUrl;
  };

  cardEditor.values = values;

  // way to pass theme colors to card editor's value color saved colors section
  cardEditor.themeColors = ['#f40afc', '#fcaf0a', '#0a8cfc', '#fc0a85']

  cardEditor.addEventListener('arcgisStatCardEditorChange', evt => {
    if (evt.detail.valid) {
      updateMetricCardValues(evt.detail.values);
    }
  }) 
  // must add context on authentication
</script>
```

## Status
Currently in development. Will grow to include additional layouts and rules for the editor to display/hide properties for specific configurations. 

## Technical
